 const hint=el('small','上传素材后自动识别产品'),heading=el('strong','商品尺寸'),list=el('div',null,'detail-size-options'),custom=el('div',null,'detail-size-custom'),part=el('select'),a=el('input'),b=el('input'),h=el('input'),add=el('button','添加'),retry=el('button','重新识别');
