 async function identify(token,items){controller=new AbortController();try{const image=await sourceImage(items);if(token!==revision)return;const data=await request('/api/detail-page/recognize',{image,numbers:items.map(x=>x.number).filter(Number.isSafeInteger),sourceCount:items.length},controller.signal);if(token!==revision)return;presets(data.category||'auto');hint.textContent=(data.name||({set:'四件套'}[data.category])||sizeParts(data.category)[0].name)+(data.category==='set'?' · 按整套选用，可直接修改尺寸':' · 勾选后加入详情页');retry.hidden=false;}catch(e){if(token!==revision)return;presets('auto');hint.textContent='暂未识别，可自定义尺寸或重试';retry.hidden=false;}finally{if(token===revision){pending=false;controls();}}}
