 retry.onclick=()=>schedule(true);options();host.hidden=false;
 return {schedule,get recognizing(){return pending;},get category(){return category;},get sizes(){return category==='set'?sets.sizes:normalizeDetailSizes(rows.filter(x=>x.selected));},setBusy(value){locked=value;controls();}};
